def priority(item: float, bins: np.ndarray) -> np.ndarray:
    mask = bins >= item
    remainder = (bins - item) % item
    return np.where(mask, -remainder, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    mask = bins >= item
    additional_items = np.floor_divide(bins - item, item, where=mask)
    return np.where(mask, additional_items, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    mask = bins >= item
    return np.where(mask, bins - item, -np.inf)
